<section class="panel"><h2>Tambah sekolah</h2><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/yayasan/sekolah') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="0"><div class="grid"><div class="field"><label>Nama sekolah</label><input name="name" required maxlength="180"></div><div class="field"><label>Slug URL</label><input name="slug" required pattern="[A-Za-z0-9_-]+" maxlength="120" placeholder="misal-sdit-al-firdaus"></div><div class="field"><label>Slogan (opsional)</label><input name="tagline" maxlength="255"></div><div class="field"><label>Logo sekolah (opsional, maks. 5 MB)</label><input type="file" name="logo_file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="field"><label>Foto sekolah / gedung (opsional, maks. 5 MB)</label><input type="file" name="photo_file" accept="image/jpeg,image/png,image/webp,image/gif"></div></div><p><button class="btn" type="submit">Tambah sekolah</button></p></form></section>
<section class="panel"><h2>Daftar sekolah</h2><div class="table-wrap"><table><thead><tr><th>Sekolah</th><th>Slug</th><th>Status</th><th>Ubah data dasar</th><th>Aksi</th></tr></thead><tbody>
<?php if (empty($schools)): ?><tr><td colspan="5">Belum ada sekolah.</td></tr><?php else: foreach ($schools as $school): ?><tr><td><?= esc($school['name']) ?></td><td><?= esc($school['slug']) ?></td><td><?= (int) $school['is_active'] === 1 ? 'Aktif' : 'Nonaktif' ?></td><td><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/yayasan/sekolah') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $school['id'] ?>"><input type="hidden" name="action" value="save"><input name="name" value="<?= esc($school['name']) ?>" required maxlength="180" aria-label="Nama sekolah"><input name="slug" value="<?= esc($school['slug']) ?>" required pattern="[A-Za-z0-9_-]+" maxlength="120" aria-label="Slug sekolah" style="margin-top:6px"><input name="tagline" value="<?= esc($school['tagline'] ?? '') ?>" maxlength="255" aria-label="Slogan" style="margin-top:6px"><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px"><?php foreach (['logo_path'=>'Logo','hero_image_path'=>'Foto'] as $imageField=>$imageLabel): ?><div style="font-size:12px"><strong><?= esc($imageLabel) ?> saat ini</strong><br><?php if (!empty($school[$imageField])): ?><img src="<?= base_url(esc($school[$imageField])) ?>" alt="<?= esc($imageLabel) ?>" style="width:100%;height:64px;object-fit:contain;background:#f3f6fb;border-radius:8px;margin:5px 0"><?php else: ?><span class="muted">Belum ada gambar</span><?php endif ?></div><?php endforeach ?></div><label style="display:block;margin-top:8px">Ganti logo</label><input type="file" name="logo_file" accept="image/jpeg,image/png,image/webp,image/gif"><label style="display:block;margin-top:8px">Ganti foto sekolah</label><input type="file" name="photo_file" accept="image/jpeg,image/png,image/webp,image/gif"><label style="display:block;margin-top:8px;font-weight:500"><input type="checkbox" name="remove_logo_path" value="1" style="width:auto"> Hapus logo</label><label style="display:block;font-weight:500"><input type="checkbox" name="remove_hero_image_path" value="1" style="width:auto"> Hapus foto</label><button class="btn btn-small" type="submit" style="margin-top:8px">Simpan</button></form></td><td><div style="display:flex;flex-wrap:wrap;gap:7px;align-items:center"><form class="inline" method="post" action="<?= site_url('admin/yayasan/sekolah') ?>" onsubmit="return confirm('Ubah status sekolah ini?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $school['id'] ?>"><input type="hidden" name="action" value="<?= (int) $school['is_active'] === 1 ? 'deactivate' : 'activate' ?>"><button class="btn btn-small <?= (int) $school['is_active'] === 1 ? 'btn-warn' : '' ?>" type="submit"><?= (int) $school['is_active'] === 1 ? 'Nonaktifkan' : 'Aktifkan' ?></button></form><form class="inline" method="post" action="<?= site_url('admin/yayasan/sekolah') ?>" onsubmit="return confirm('Yakin ingin menghapus sekolah <?= esc($school['name'], 'js') ?>? Tindakan ini tidak dapat dibatalkan.')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $school['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-small btn-delete" type="submit">Hapus</button></form></div></td></tr><?php endforeach; endif ?>
</tbody></table></div></section></main></div></body></html>
